pub fn icon<'a, Message: 'a>(svg_raw: &'static str, size: f32, color: Color) -> Element<'a, Message> {
    let handle = svg::Handle::from_memory(svg_raw.as_bytes());
    svg::Svg::new(handle)
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
        .style(move |_theme: &Theme, _status| svg::Style {
            color: Some(color),
        })
        .into()
}
